<?php
require __DIR__.'/../app/bootstrap.php';$u=require_admin();require_experience();$title=t('Contact requests');
if(post()){$id=(int)val('id');$message=one('SELECT * FROM contact_messages WHERE id=?',[$id]);if($message && in_array(val('status'),['new','resolved'],true)){q('UPDATE contact_messages SET status=? WHERE id=?',[val('status'),$id]);flash(t('Request updated.'));}go('admin/contact-messages.php');}
$selected=max(0,(int)param('id'));$page=max(1,(int)param('page'));$offset=($page-1)*30;$messages=$selected?all('SELECT * FROM contact_messages WHERE id=?',[$selected]):all('SELECT * FROM contact_messages ORDER BY id DESC LIMIT 31 OFFSET '.$offset);$more=count($messages)>30;$messages=array_slice($messages,0,30);
require ROOT.'/app/workspace-start.php'; ?>
<div class="page-heading"><h1><?=e(t('Contact requests'))?></h1><?php if($selected): ?><a class="pill compact" href="<?=e(url('admin/contact-messages.php'))?>"><?=e(t('All requests'))?></a><?php endif ?><p><?=e(t('Account details and messages submitted by customers and sellers.'))?></p></div>
<?php if(!$messages): ?><section class="panel"><p><?=e(t('No requests yet.'))?></p></section><?php endif ?>
<?php foreach($messages as $m): ?><article class="panel padded space-top" id="request-<?=$m['id']?>"><div class="order-meta"><strong><?=e(t('Request #'))?><?=$m['id']?> · <?=e(t(ucfirst($m['account_type'])))?></strong><span><?=e(t(ucfirst($m['status'])))?> · <?=e(local_time($m['created_at']))?></span></div><h2><?=e($m['full_name'])?></h2><p><?=e($m['email'])?> · <?=e($m['phone'])?></p><p class="contact-description"><?=nl2br(e($m['description']))?></p><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$m['id']?>"><button class="pill compact" name="status" value="<?=$m['status']==='resolved'?'new':'resolved'?>"><?=e(t('Mark'))?> <?=$m['status']==='resolved'?'new':'resolved'?></button></form></article><?php endforeach ?>
<nav class="pagination"><?php if($page>1): ?><a class="pill" href="?page=<?=$page-1?>"><?=e(t('Previous'))?></a><?php endif ?><?php if($more): ?><a class="pill" href="?page=<?=$page+1?>"><?=e(t('Next'))?></a><?php endif ?></nav><?php require ROOT.'/app/workspace-end.php'; ?>
